contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        // Record the previous owner to later prove the privileged call had an effect.
        address previousOwner = c.owner();

        // Attempt the privileged setter. The test contract is not the admin,
        // so we cannot legally make this call succeed without first compromising
        // the admin account. We instead observe the behavior on the access-control boundary.
        bool reverted;
        try c.setOwner(newOwner) returns (bool success) {
            // If it somehow succeeds, it must report true.
            reverted = false;
            assert(success == true);
        } catch {
            // Correct behavior: the non-admin call reverts.
            reverted = true;
        }

        // General rule: because the test harness account is not the admin,
        // every call to setOwner must revert, and therefore owner must remain
        // unchanged as observed through the public getter.
        assert(reverted && c.owner() == previousOwner);
    }
}

