contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _owner, bool _asAdmin) public payable {
        address originalOwner = c.owner();

        bool reverted;
        bool returned;

        if (_asAdmin) {
            try c.setOwner(_owner) returns (bool success) {
                returned = success;
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.setOwner(_owner) returns (bool success) {
                returned = success;
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted) {
            assert(returned && c.owner() == _owner);
        } else {
            assert(c.owner() == originalOwner);
        }
    }
}

